updateRule:
(@request.auth.collectionName = \hkp_staff_users" && @request.auth.is_active = true && (@request.auth.role = "staff" || @request.auth.role = "admin") && (
  @request.body.status:isset = false
  || (status = "pending" && (@request.body.status = "borrowed" || @request.body.status = "rejected" || @request.body.status = "cancelled"))
  || (status = "borrowed" && @request.body.status = "return_pending")
  || (status = "return_pending" && @request.body.status = "returned")
)) || (public_token_hash != "" && public_token_hash = @request.headers.x_hkp_token && status = "pending" && @request.body.status = "cancelled") || (public_token_hash != "" && public_token_hash = @request.headers.x_hkp_token && borrower_name_hash = @request.headers.x_hkp_name && borrower_phone = @request.headers.x_hkp_phone && status = "borrowed" && @request.body.status = "return_pending")"
